{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "ref",
      "type": "React.Ref<HTMLInputElement>",
      "description": "Ref forwarded to the underlying <input> element."
    },
    {
      "name": "label",
      "type": "string",
      "description": "Label text for the checkbox (always rendered for accessibility).",
      "required": true
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Whether to visually hide the label (still accessible to screen readers).",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Description text displayed below the label."
    },
    {
      "name": "value",
      "type": "boolean | 'indeterminate'",
      "description": "Whether the checkbox is checked, unchecked, or indeterminate.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(checked: boolean, e: ChangeEvent<HTMLInputElement>) => void",
      "description": "Callback fired when the checkbox state changes."
    },
    {
      "name": "changeAction",
      "type": "(checked: boolean, e: ChangeEvent<HTMLInputElement>) => void | Promise<void>",
      "description": "Async action on change. Fires after onChange if not prevented. Shows loading spinner while pending."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Whether the checkbox is in a loading state. Shows spinner and prevents interaction.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether the checkbox is disabled.",
      "default": "false"
    },
    {
      "name": "htmlName",
      "type": "string",
      "description": "The HTML name attribute for the underlying checkbox input, useful for form submissions (submits \"on\" when checked)."
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the checkbox is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and keeps the checkbox focusable via aria-disabled (toggling stays blocked). Use this instead of wrapping a disabled CheckboxInput in Tooltip. Disabled controls swallow the hover events an external Tooltip needs."
    },
    {
      "name": "isReadOnly",
      "type": "boolean",
      "description": "Whether the checkbox is read-only. Displays the current state at full opacity but prevents interaction. Unlike `isDisabled`, read-only checkboxes are not visually dimmed.",
      "default": "false"
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Whether the field is optional. Mutually exclusive with isRequired.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Whether the checkbox is required. Mutually exclusive with isOptional.",
      "default": "false"
    },
    {
      "name": "size",
      "type": "'sm' | 'md'",
      "description": "The size of the checkbox. sm for compact layouts, md for default. Under a coarse pointer a labelled checkbox’s target grows toward 44 px through an invisible hit area. It never shrinks below the row and stops at half the gap to a closer neighbour; nothing changes size.",
      "default": "'md'"
    },
    {
      "name": "onFocus",
      "type": "(e: FocusEvent<HTMLInputElement>) => void",
      "description": "Callback fired when the checkbox receives focus."
    },
    {
      "name": "onBlur",
      "type": "(e: FocusEvent<HTMLInputElement>) => void",
      "description": "Callback fired when the checkbox loses focus."
    },
    {
      "name": "labelIcon",
      "type": "ReactNode | IconType",
      "description": "Semantic icon name or custom content displayed before the label text. See `astryx docs icons` for valid semantic names."
    },
    {
      "name": "status",
      "type": "{ type: 'error' | 'warning' | 'success', message: string }",
      "description": "Status indicator. Displays a colored message box below the checkbox and sets aria-invalid for errors."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
